use serde_json::{json, Value};
use crate::编号与码面::错误码;
const 最大行号:u32=1_048_576; const 最大列号:u32=16_384;
pub(crate) fn 解析纯文本(源文本:&str)->Result<String,u32>{if 源文本.len()>262144{return Err(错误码::内容不合法)};let mut 块列表=Vec::new();let mut 行号=1u32;for 源文本 in 源文本.split_inclusive('\n'){let 源文本=源文本.strip_suffix('\n').unwrap_or(源文本);let 源文本=源文本.strip_suffix('\r').unwrap_or(源文本);块列表.push(json!({"正文":源文本,"行起":行号,"行止":行号}));行号+=1;}if 源文本.is_empty(){块列表.push(json!({"正文":"","行起":1,"行止":1}));}else if 源文本.ends_with('\n'){块列表.push(json!({"正文":"","行起":行号,"行止":行号}));}Ok(json!({"原文":源文本,"块":块列表}).to_string())}
pub(crate) fn 解析地址文本(源文本:&str)->Result<String,u32>{let 源文本=源文本.trim();if 源文本.is_empty(){return Err(错误码::地址不合法)};let(工作表,单元格)=if let Some(游标)=源文本.rfind('!'){let 工作表=源文本[..游标].trim().trim_matches('\'').to_string();if 工作表.is_empty(){return Err(错误码::地址不合法)};(Some(工作表),&源文本[游标+1..])}else{(None,源文本)};let 字节=单元格.as_bytes();let mut 游标=0usize;let 列绝对=字节.get(0)==Some(&b'$');if 列绝对{游标+=1};let 列起=游标;while 游标<字节.len()&&字节[游标].is_ascii_alphabetic(){游标+=1};if 游标==列起{return Err(错误码::地址不合法)};let mut 列号=0u32;for 单字节 in 单元格[列起..游标].bytes(){列号=列号.checked_mul(26).and_then(|值|值.checked_add((单字节.to_ascii_uppercase()-b'A'+1)as u32)).ok_or(错误码::地址越界)?;}let 行绝对=字节.get(游标)==Some(&b'$');if 行绝对{游标+=1};let 行起=游标;while 游标<字节.len()&&字节[游标].is_ascii_digit(){游标+=1};if 游标==行起||游标!=字节.len(){return Err(错误码::地址不合法)};let 行号=单元格[行起..].parse::<u32>().map_err(|_|错误码::地址不合法)?;if 行号==0||列号==0{return Err(错误码::地址不合法)};if 行号>最大行号||列号>最大列号{return Err(错误码::地址越界)};Ok(json!({"工作表":工作表,"行号":行号,"列号":列号,"行绝对":行绝对,"列绝对":列绝对}).to_string())}
pub(crate) fn 格式化地址文本(源文本:&str)->Result<String,u32>{let 值:Value=serde_json::from_str(源文本).map_err(|_|错误码::地址不合法)?;let 行号=值.get("行号").and_then(Value::as_u64).ok_or(错误码::地址不合法)? as u32;let 列号=值.get("列号").and_then(Value::as_u64).ok_or(错误码::地址不合法)? as u32;if 行号==0||列号==0||行号>最大行号||列号>最大列号{return Err(错误码::地址越界)};let mut 地址文本=String::new();if let Some(工作表)=值.get("工作表").and_then(Value::as_str){地址文本.push_str(工作表);地址文本.push('!');}if 值.get("列绝对").and_then(Value::as_bool).ok_or(错误码::地址不合法)?{地址文本.push('$')}let mut 列号文本=String::new();let mut 列号=列号;while 列号>0{列号文本.push((b'A'+((列号-1)%26)as u8)as char);列号=(列号-1)/26;}地址文本.push_str(&列号文本.chars().rev().collect::<String>());if 值.get("行绝对").and_then(Value::as_bool).ok_or(错误码::地址不合法)?{地址文本.push('$')}地址文本.push_str(&行号.to_string());Ok(地址文本)}
